package config

// How far a base image may move when remediation proposes a bump (§3.2).
//
// The names are stated here and in internal/remediation, which config must not
// import; TestTheTrackNamesMatchTheConfig (internal/remediation) holds the two
// in step — the same arrangement as forge.type and the container engines.
const (
	// BaseImageTrackSameLine keeps the major version: 3.18 may become 3.21,
	// never 4.0. The default, because a scan proves the CVEs are gone but not
	// that an application survives a major upgrade.
	BaseImageTrackSameLine = "same-line"
	// BaseImageTrackNextMajor also allows the next major version that exists.
	BaseImageTrackNextMajor = "next-major"
)

// BaseImageTracks is the set scan.base_image_track cycles through in the
// configuration view.
func BaseImageTracks() []string {
	return []string{BaseImageTrackSameLine, BaseImageTrackNextMajor}
}
package config

import "testing"

// The setting is written on load so the configuration view, which cycles a
// closed set, has a value to start from.
func TestTheBaseImageTrackDefaultsToSameLine(t *testing.T) {
	cfg := &Config{}
	if err := applyDefaults(cfg); err != nil {
		t.Fatalf("applyDefaults: %v", err)
	}
	if cfg.Scan.BaseImageTrack != BaseImageTrackSameLine {
		t.Errorf("BaseImageTrack = %q, want %q", cfg.Scan.BaseImageTrack, BaseImageTrackSameLine)
	}
	if Default().Scan.BaseImageTrack != BaseImageTrackSameLine {
		t.Errorf("Default() BaseImageTrack = %q, want %q", Default().Scan.BaseImageTrack, BaseImageTrackSameLine)
	}
}

// A chosen value is kept, and a value outside the set is not rewritten behind
// the user's back — remediation reads it as same-line.
func TestAConfiguredBaseImageTrackIsKept(t *testing.T) {
	for _, value := range []string{BaseImageTrackNextMajor, "typo"} {
		cfg := &Config{Scan: ScanConfig{BaseImageTrack: value}}
		if err := applyDefaults(cfg); err != nil {
			t.Fatalf("applyDefaults: %v", err)
		}
		if cfg.Scan.BaseImageTrack != value {
			t.Errorf("BaseImageTrack = %q, want %q kept", cfg.Scan.BaseImageTrack, value)
		}
	}
}
