// busyLabel returns the action running on an item, and whether there is one.
func (m *Model[T]) busyLabel(item T) (string, bool) {
	if m.cfg.Key == nil || len(m.busy) == 0 {
		return "", false
	}
	label, ok := m.busy[m.cfg.Key(item)]
	return label, ok
}

// SetTokenActive toggles one of the bar's filter tokens and re-applies it.
func (m *Model[T]) SetTokenActive(label string, active bool) {
	m.bar.SetTokenActive(label, active)
	m.rebuild()
	m.Remeasure() // a toggle is a user action on a settled population
}

// IsTokenActive reports whether a toggle filter is on.
func (m *Model[T]) IsTokenActive(label string) bool { return m.bar.IsTokenActive(label) }

// rebuild filters, sorts, writes the rows and puts the cursor somewhere real.
func (m *Model[T]) rebuild() {
	m.visible = m.sorted(m.filtered())

	// The natural widths are taken here because the cells are already being
	// built: the measurement is a lipgloss.Width per cell on a walk that
	// happens anyway. Promoting them to the solver is a separate decision
	// (see Remeasure) — this only keeps the answer current.
	//
	// The header counts. A content column narrower than its own title truncates
	// the one cell that says what the column is, and "the width the content
	// wants" plainly includes being able to name itself.
}

// filtered applies the search query and the toggle filters.
func (m *Model[T]) filtered() []T {
	query := strings.ToLower(strings.TrimSpace(m.bar.SearchQuery()))
	active := m.activeTokens()

	out := make([]T, 0, len(m.items))
	for _, item := range m.items {
		if m.cfg.TokenMatch != nil && !m.cfg.TokenMatch(item, active) {
			continue
		}
		if query != "" && !m.matchesQuery(item, query) {
			continue
		}
		out = append(out, item)
	}
	return out
}

func (m *Model[T]) activeTokens() map[string]bool {
	active := make(map[string]bool, len(m.cfg.Tokens))
	for _, tok := range m.cfg.Tokens {
		if m.bar.IsTokenActive(tok.Label) {
			active[tok.Label] = true
		}
	}
	return active
}

// matchesQuery tests the query against each searchable column and then against
// Path is what ties a file to its surface, and it is there so the
// declaration is checkable: without it, "these letters are local to this
// view" is verified by merging every list, and `l` declared for netdiag
// would excuse `l` in the registries. Matching is done on the longest
// prefix, so netdiag/ports can narrow down netdiag.
type Surface struct {
	Name string
	Path string
	Keys []string
}

// localToggles inventories the lowercase letters used as display or filter
// toggles. They change nothing, so their meaning is local and the same
// letter can serve twice without contradiction — `l` is the protocol in
// netdiag and the LOW severity in security.
//
// A file that matches no surface is entitled to no lowercase letter at
// all: that is the default, and it is what makes the list worth keeping
// up to date.
var localToggles = []Surface{
	{"containers", "ui/containers/", []string{"r", "p", "s", "t", "z"}},
	{"viewer", "ui/viewer/", []string{"f", "c", "w", "v", "t", "n", "g", "s"}},
	{"netdiag/ports", "ui/netdiag/ports_model.go", []string{"t", "u", "l", "e", "n", "z"}},
	{"netdiag/checks", "ui/netdiag/", []string{"p"}},
	{"oci/browser", "ui/oci_resources/browser_", []string{"r"}},
	{"security/findings", "ui/security/", []string{"c", "h", "m", "l"}},
	// g opens the fuzzy-find prompt across the whole workspaces tree. Same
	// justification as the viewer's g: the jump takes an argument (the typed
	// query), which is not a role home/end/G could ever cover.
	{"workspaces", "ui/workspaces/", []string{"g"}},
	// The same prompt over the forge index: every namespace and repository
	// the session can see, at any depth.
	{"forge/explorer", "ui/forge/explorer/", []string{"g"}},
}

// LocalToggles returns the declared surfaces.
func LocalToggles() []Surface {
	return append([]Surface(nil), localToggles...)
}

// SurfaceFor ties a file path to its surface, by longest prefix. The
// second return says whether a surface was found.
func SurfaceFor(path string) (Surface, bool) {
	var best Surface
	found := false
	for _, s := range localToggles {
		if !strings.Contains(path, s.Path) {
			continue
