		{"severity alone, dropped", "baseline", map[string]bool{"critical": true}, "KSV-0017@deploy.yaml", false},
		{"both, hidden by the profile", "baseline", map[string]bool{pssToken: true, "critical": true}, "KSV-0030@deploy.yaml", false},
